import sys
from collections import defaultdict, deque

def bfs(tree, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def lca(parents, depth, u, v):
    if depth[u] < depth[v]:
        u, v = v, u
    diff = depth[u] - depth[v]
    for _ in range(diff.bit_length()):
        if diff & 1:
            u = parents[u]
        diff >>= 1
    while u != v:
        u = parents[u]
        v = parents[v]
    return u

n, m = map(int, sys.stdin.readline().split())
roads = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n - 1)]
citizens = [tuple(map(int, sys.stdin.readline().split())) for _ in rage(m)]

tree = defaultdict(list)
for u, v in roads:
    tree[u].append(v)
    tree[v].append(u)

parents = {1: None}
depth = {1: 0}
queue = deque([1])
while queue:
    node = queue.popleft()
    for neighbor in tree[node]:
        if neighbor not in parents:
            parents[neighbor] = node
            depth[neighbor] = depth[node] + 1
            queue.append(neighbor)

edge_indices = {}
for i, (u, v) in enumerate(roads, 1):
    if depth[u] > depth[v]:
        u, v = v, u
    edge_indices[(u, v)] = i

paths = []
for xi, yi in citizens:
    path = set()
    while xi != yi:
        if depth[xi] > depth[yi]:
            path.add((xi, parents[xi]))
            xi = parents[xi]
        elif depth[xi] < depth[yi]:
            path.add((parents[yi], yi))
            yi = parents[yi]
        else:
            path.add((xi, parents[xi]))
            path.add((parents[yi], yi))
            xi = parents[xi]
            yi = parents[yi]
    paths.append(path)

edge_count = defaultdict(int)
for path in paths:
    for edge in path:
        edge_count[edge] += 1

total_puppies = 0
citizen_puppies = []
guardian_puppies = []

for xi, yi in citizens:
    if edge_count[(min(xi, parents[xi]), max(xi, parents[xi]))] > 1 or edge_count[(min(yi, parents[yi]), max(yi, parents[yi]))] > 1:
        citizen_puppies.append(citizens.index((xi, yi)) + 1)
        total_puppies += 1
        for edge in paths[citizens.index((xi, yi))]:
            edge_count[edge] -= 1

for (u, v), count in edge_count.items():
    if count > 0:
        guardian_puppies.append(edge_indices[(u, v)])
        total_puppies += 1

print(total_puppies)
print(len(citizen_puppies), *citizen_puppies)
print(len(guardian_puppies), *guardian_puppies)
